            pub(super) fn drain<K>(root: Option<Box<Node<K, ()>>>, values: &mut Vec<K>) {
                if let Some(mut node) = root {
                    let left = node.left.take();
                    let right = node.right.take();
                    drain(left, values);
                    values.push(node.key);
                    drain(right, values);
